(function(){const label=document.getElementById('calculator-step');if(!label)return;function update(){const results=document.getElementById('dashboard');label.textContent=results && getComputedStyle(results).display!=='none'?'Step 3 of 3 · Review estimate':document.querySelector('#screen2.active')?'Step 2 of 3 · Operating assumptions':'Step 1 of 3 · Basic information';}new MutationObserver(update).observe(document.querySelector('main'),{subtree:true,attributes:true,attributeFilter:['class','style']});})();
